source("h.R")
recount <- function(s) {
  m <- rows(s, "meta"); b <- rows(s, "blobs"); c <- ctr(s)
  inl <- sum(vapply(m, function(r) if (isTRUE(r$inline)) r$bytes else 0, 0))
  fl <- blobs(s); fsz <- sum(file.size(file.path(cache_dir(s), "blobs", fl)))
  vals <- D$engine_read(s$engine, function(txn) { g <- D$engine_scan(txn, D$engine_db(s$engine, "values"), as="character", values=TRUE); sum(lengths(g$values)) })
  ok <- c$bytes_inline == inl && inl == vals && c$bytes_blob == fsz && setequal(basename(fl), names(b)) && nrow(cache_check(s, hash = TRUE)) == 0 && length(tmpf(s)) == 0 &&
    all(file.mode(file.path(cache_dir(s), "blobs", fl)) == as.octmode("444"))
  cat(sprintf("  [%s] count=%d inline=%g/%g/%g blob=%g/%g files=%d\n", if (ok) "ok" else "MISMATCH", length(m), c$bytes_inline, inl, vals, c$bytes_blob, fsz, length(fl)))
  invisible(ok)
}
big <- as.raw(rep(7, 200)); small <- as.raw(1:5)
s <- newc(inline_max = 50)
cat("blob->inline->blob\n"); cache_set(s, "k", big); recount(s); cache_set(s, "k", small); recount(s); stopifnot(identical(cache_get(s,"k"), small)); cache_set(s, "k", big); recount(s); stopifnot(identical(cache_get(s,"k"), big))
cat("same-bytes overwrite\n"); cache_set(s, "k", big); recount(s); print(rows(s,"blobs")[[1]]$refs)
cat("set pop set\n"); stopifnot(identical(cache_pop(s, "k"), big)); recount(s); cache_set(s, "k", big); recount(s); stopifnot(identical(cache_get(s,"k"), big))
cat("pop with shared blob\n"); cache_set(s, "k2", big); stopifnot(identical(cache_pop(s, "k"), big)); recount(s); stopifnot(identical(cache_get(s,"k2"), big))
cat("transact: delete then re-set same content\n")
cache_transact(s, { cache_delete(s, "k2"); cache_set(s, "k3", big) }); recount(s); stopifnot(identical(cache_get(s,"k3"), big))
cat("transact: set, delete, error\n")
print(try_(cache_transact(s, { cache_set(s, "n1", as.raw(rep(9, 300))); cache_delete(s, "k3"); stop("boom") }))); recount(s); print(blobs(s)); print(try_(length(cache_get(s,"k3"))))
print(cache_check(s)[,c("kind","key")])
cat("transact: delete k3, re-set k3 same, error (file replaced, rollback)\n")
cache_check(s, repair=TRUE)
print(try_(cache_transact(s, { cache_delete(s, "k3"); cache_set(s, "k4", big); stop("boom") }))); recount(s); stopifnot(identical(cache_get(s,"k3"), big)); print(cache_has(s, "k4"))
cat("transact: pop inside, then read\n")
r <- cache_transact(s, { v <- cache_pop(s, "k3"); cache_set(s, "k5", v); length(v) }); print(r); recount(s); stopifnot(identical(cache_get(s,"k5"), big))
cat("transact: pop file entry w/ shared? pop then error\n")
print(try_(cache_transact(s, { v <- cache_pop(s, "k5"); stop("boom") }))); recount(s); print(try_(length(cache_get(s,"k5")))); print(tmpf(s))
cat("expire then reclaim\n")
cache_set(s, "x1", big, expire = -1); cache_set(s, "x2", big, expire = 3600); print(cache_has(s, c("x1","x2"))); recount(s); cache_expire(s); recount(s); stopifnot(identical(cache_get(s,"x2"), big)); print(cache_count(s))
cat("add over expired blob entry with inline\n")
cache_set(s, "y", big, expire = -1); print(cache_add(s, "y", small)); recount(s); print(cache_get(s, "y"))
cat("mset dupes\n")
cache_mset(s, list(m1 = big, m2 = big, m1 = small, m3 = as.raw(rep(8,200)))); recount(s); print(cache_get(s, "m1")); print(sapply(rows(s,"blobs"), `[[`, "refs"))
cat("touch\n"); cache_touch(s, "m2", 0); print(cache_has(s, "m2")); cache_expire(s); recount(s); stopifnot(identical(cache_get(s,"m3"), as.raw(rep(8,200))))
cat("evict tag/prefix\n"); cache_set(s, "t1", big, tags = c("a","b")); cache_set(s, "t2", big, tags = "a"); cache_evict(s, tag = "b"); recount(s); stopifnot(identical(cache_get(s,"t2"), big)); cache_evict(s, prefix = "t"); recount(s)
cat("incr on expired / with tags\n"); cache_incr(s, "c", by = 5); cache_touch(s, "c", 100); print(cache_incr(s, "c")); print(cache_info(s, "c")$expires > Sys.time()); recount(s)
cache_set(s, "c2", 5); print(try_(cache_incr(s, "c2")))
print(cache_incr(s, "neg", by = -2^53)); print(try_(cache_decr(s, "neg"))); print(cache_incr(s,"neg", by = 2^53)); print(cache_incr(s,"big", default = 2^53 - 1)); print(cache_get(s, "big") == 2^53)
print(cache_incr(s, "m", by = -1)); print(cache_incr(s, "m", by = -2^32)); print(cache_incr(s, "m", by = 2^32+1)); recount(s)
cat("clear\n"); cache_clear(s); recount(s); print(blobs(s))
cat("as_cachem / memoise equivalence\n")
cm <- as_cachem(s); cm$set("ck", big); cache_set(s, "sk", big); recount(s); print(sapply(rows(s,"blobs"), `[[`, "refs")); print(identical(cm$get("ck"), big))
f <- cache_memoise(function(x) big, s, name = "f"); invisible(f(1)); invisible(f(2)); recount(s); print(sapply(rows(s,"blobs"), `[[`, "refs")); print(identical(f(1), big))
